head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gBondYn;
scwin.vIMKT_ID;
scwin.vDepCd;
scwin.gIsurCd;
scwin.vScrenID = 'ULDSTF26601.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.openNew = async function() {
    await $c.frame.CreateDialogFrame("child01", "/dsclsrch/ULDSTF26605.gfm", "신규", 100, 100, 480, 210 + 40, "window");
};
scwin.fn_Init = function() {
    var vIBAS_YY = $c.stf.getQuery(frame.srcUrl, "BAS_YY");
    var vIBAS_ACNTCLS_MM = $c.stf.getQuery(frame.srcUrl, "BAS_ACNTCLS_MM");
    var vIWRTRPT_KIND_CD = $c.stf.getQuery(frame.srcUrl, "WRTRPT_KIND_CD");
    scwin.vDepCd = $c.stf.getQuery(frame.srcUrl, "DEP_CD");
    $c.stf.setObjectValue(txb_BAS_ACNTCLS_MM, $c.stf.getQuery(frame.srcUrl, "BAS_ACNTCLS_MM"));
    $c.stf.setObjectValue(txb_WRTRPT_KIND_CD, $c.stf.getQuery(frame.srcUrl, "WRTRPT_KIND_CD"));
    $c.stf.setObjectValue(txb_BAS_YY, $c.stf.getQuery(frame.srcUrl, "BAS_YY"));
    $c.stf.setObjectValue(txb_BAS_ACNTCLS_MM_YY, $c.stf.getQuery(frame.srcUrl, "BAS_ACNTCLS_MM_YY"));
    $c.stf.setObjectValue(txb_WRTRPT_KIND_CDNM, $c.stf.getQuery(frame.srcUrl, "WRTRPT_KIND_CDNM"));
    $c.stf.setObjectValue(txb_DEPT, $c.stf.getQuery(frame.srcUrl, "DEP_CDNM"));
    $c.stf.setObjectValue(edt_SCHDL_DD, $c.stf.getQuery(frame.srcUrl, "WRTRPT_SUBMIT_SCHDL_DD"));
    scwin.vIMKT_ID = $c.stf.getQuery(frame.srcUrl, "MKT_ID");
    scwin.gBondYn = 'N`';
    $c.stf.setObjectValue(txb_MKT_CD, scwin.vIMKT_ID);
    if (scwin.vIMKT_ID == '1') {
        $c.stf.setObjectValue(txb_MKT_NM, '유가');
    } else if (scwin.vIMKT_ID == '2') {
        $c.stf.setObjectValue(txb_MKT_NM, '코스닥');
    } else if (scwin.vIMKT_ID == '4') {
        $c.stf.setObjectValue(txb_MKT_NM, '채권');
        scwin.gBondYn = 'Y';
    }
    if (scwin.gBondYn == 'Y') {
        $c.cm.setColumnProp(grd_Grid, "DEL_YN", "Show", false);
    }
};
scwin.fn_read = function(GridID, row, colid) {
    if (row < 1) return;
    var objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..	
    //DEL_YN	
    if (colid == "DEL_YN") {
        // 수정용 화면.
        if (confirm("삭제를 하시겟습니까?")) {
            scwin.fn_readDel(GridID, row);
        }
    } else if (colid == "COM_ABBRV") {
        scwin.gIsurCd = dts_Grid.getCellData(row, "ISUR_CD");
        $c.stf.fn_PopupCorpInfo();
    } else if (colid == "SUBMIT_YN") {
        var AcptNo = objDataID.getCellData(row, "ACPT_NO");
        if (AcptNo == "") {
            if (scwin.vIMKT_ID == '2') {
                // 코스닥일때만 적용
                // 미제출일때만 링크한다.	
                scwin.fn_OpenNSubmitMgt(objDataID.getCellData(row, "ISUR_CD"));
            }
        }
    }
};
scwin.fn_OpenNSubmitMgt = async function(obj) {
    var url = "/dsclsrch/ULDSTF26610.gfm?ISUR_CD=" + obj;
    var winTitle = "정기보고서 미제출법인 관리";
    await $c.frame.CreateDialogFrame("NSUBMITINFO1", url, winTitle, 50, 100, 700, 330, "window");
};
scwin.fn_readDel = function(GridID, row) {
    //작업해야함 
    var objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..		

    var vIBAS_YY = objDataID.getCellData(row, "BAS_YY");
    var vIBAS_ACNTCLS_MM = objDataID.getCellData(row, "BAS_ACNTCLS_MM");
    var vIWRTRPT_KIND_CD = objDataID.getCellData(row, "WRTRPT_KIND_CD");
    var vIISUR_CD = objDataID.getCellData(row, "ISUR_CD");
    var vIACP_YN = $c.stf.getObjectValue(cmb_ACP_YN);
    trs_Save.Action = encodeURI("/SubmitStatus.do?method=removeCompaySubmitStatus&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Grid)";
    trs_Save.Parameters = "BAS_YY=" + vIBAS_YY + ",BAS_ACNTCLS_MM=" + vIBAS_ACNTCLS_MM + ",WRTRPT_KIND_CD=" + vIWRTRPT_KIND_CD + ",MKT_ID=" + scwin.vIMKT_ID + ",ACP_YN=" + vIACP_YN + ",ISUR_CD=" + vIISUR_CD;
    trs_Save.Post();
};
scwin.fn_Search = function() {
    var vIBAS_YY = $c.stf.getObjectValue(txb_BAS_YY);
    var vIBAS_ACNTCLS_MM = $c.stf.getObjectValue(txb_BAS_ACNTCLS_MM);
    var vIWRTRPT_KIND_CD = $c.stf.getObjectValue(txb_WRTRPT_KIND_CD);
    var vIISUR_CD = $c.stf.getObjectValue(txb_ISUR_CD);
    var vIACP_YN = $c.stf.getObjectValue(cmb_ACP_YN);
    $c.cm.ShowWin(grd_Grid);
    var url = "/SubmitStatus.do?method=readSubmitStatus";
    url += "&BAS_YY=" + vIBAS_YY;
    url += "&BAS_ACNTCLS_MM=" + vIBAS_ACNTCLS_MM;
    url += "&WRTRPT_KIND_CD=" + vIWRTRPT_KIND_CD;
    url += "&ISUR_CD=" + vIISUR_CD;
    url += "&ACP_YN=" + vIACP_YN;
    url += "&MKT_ID=" + scwin.vIMKT_ID;
    url += "&DEP_CD=" + scwin.vDepCd;
    url += "&BOND_YN=" + scwin.gBondYn;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Grid.DataID = encodeURI(url);
    dts_Grid.Reset();
};
scwin.fn_HideDebugCtrls = function() {
    /*
    showObj(txb_BAS_ACNTCLS_MM, false);
    showObj(txb_WRTRPT_KIND_CD, false);
    //showObj(txb_ISUR_CD, false);
    showObj(txb_MKT_CD, false);
    */
    $c.stf.showObj(panel_debug, false);
};
scwin.grd_Grid_OnClick = function(row, colid) {
    //fn_read(grd_Grid, row, colid);

};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    scwin.fn_read(grd_Grid, row, colid);
};
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert("성공적으로 처리 되었습니다.");
    scwin.fn_Search();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert('trs_Save.OnFail() :' + trs_Save.ErrorMsg);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.btn_ToExcel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, "제출현황목록", "", "2");
};
scwin.btn_New_onclick = function() {
    scwin.openNew();
};
scwin.btn_ISUR_CD_onclick = function() {
    if (scwin.gBondYn == 'Y') {
        $c.cm.IsurcdSearchBond(txb_ISUR_CD, txb_COM_NM);
    } else {
        $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
    }
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
    Grd_com_isur.style.left = "92px";
    Grd_com_isur.style.top = "75px";
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.gform_onload = function() {
    scwin.fn_HideDebugCtrls();
    //fn_SetCode();

    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
    scwin.fn_Init();
    scwin.fn_Search();
};
